const fs = require('fs');

class MinHeap {
  constructor() {
    this.heap = [];
  }

  size() {
    return this.heap.length;
  }

  push(item) {
    this.heap.push(item);
    this._up(this.heap.length - 1);
  }

  pop() {
    const h = this.heap;
    if (h.length === 1) return h.pop();

    const top = h[0];
    h[0] = h.pop();
    this._down(0);
    return top;
  }

  _up(i) {
    const h = this.heap;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (h[p][0] <= h[i][0]) break;
      [h[p], h[i]] = [h[i], h[p]];
      i = p;
    }
  }

  _down(i) {
    const h = this.heap;
    const n = h.length;

    while (true) {
      let smallest = i;
      const l = 2 * i + 1;
      const r = 2 * i + 2;

      if (l < n && h[l][0] < h[smallest][0]) smallest = l;
      if (r < n && h[r][0] < h[smallest][0]) smallest = r;

      if (smallest === i) break;

      [h[i], h[smallest]] = [h[smallest], h[i]];
      i = smallest;
    }
  }
}

