  adj[a].push([b, c]);
  adj[b].push([a, c]);
}

const INF = Infinity;
const dist = Array(N + 1).fill(INF);
dist[1] = 0;

const heap = new MinHeap();
heap.push([0, 1]);

while (heap.size() > 0) {
  const [d, u] = heap.pop();

  if (d !== dist[u]) continue;
  if (u === N) break;

  for (const [v, w] of adj[u]) {
    const nd = d + w;
    if (nd < dist[v]) {
      dist[v] = nd;
      heap.push([nd, v]);
    }
  }
}

